      "title": "翼华科技贾淑芸： 在网络算力这一层，让每个Token更便宜",
      "summary": "首页 翼华科技贾淑芸： 在网络算力这一层，让每个Token更便宜 武守哲 索虏岛夷 7月18日下午，由观察者网、WAIC CONNECT主办，半导体行业观察协办的“「重构算力」——AI算力需求与供给的结构性重构产业链接会”在上海张江科学会堂举办。作为WAIC 2026同期的一场重要产业活动，这场汇聚了政府、产业方与需求",
