      "id": "aHR0cHM6Ly93d3cuZ3Vh",
      "title": "一台晚会能办成什么样，取决于机器人",
      "summary": "机器人走出实验室的前夜，黎明的曙光已经依稀可见。现在的问题不再是“能不能”，而是“怎么做”和“多快”。",
      "source": "观察者网-产业科技",
